				_ = pack.Close()
				h.events = append(h.events, fmt.Sprintf("push:%d", len(cmds)))
				h.packPushes = append(h.packPushes, slices.Clone(cmds))
				return nil
			},
		},
		DesiredRefs:      desired,
		TargetRefs:       map[plumbing.ReferenceName]plumbing.Hash{},
